//! Provenance lock for the versioned CUDA kernels (runs in CI, no GPU, no nvcc).
//!
//! `cargo` never calls `nvcc`: the PTX under `claymore-cuda/src/kernels` is a
//! committed artefact regenerated by hand from the `.cu` / `.cuh` sources. A
//! source edited without regenerating its PTX (or the reverse) would silently
//! break the CUDA <-> CPU parity that `kernel_order_parity.rs` transcribes, and
//! nothing on the CI runner could tell. This test pins the SHA-256 of every
//! source and of every PTX file, so that any change to one of them fails CI
//! until the author consciously updates this manifest **in the same commit**.
//!
//! Updating the manifest is a deliberate act with a procedure:
//! 1. regenerate the PTX (`nvcc 13.0 -fmad=false`, see the M10.4 parity report
//!    section 5.2) and verify it is reproducible;
//! 2. replay the GPU non-regression campaign (21/21 primitives at `0e0`, chain
//!    `0.000000 / 0.000000`, 256/256 positions, peak VRAM <= 28 GiB);
//! 3. update the digests below and the report's artefact table (section 8.2).

use std::path::PathBuf;

use claymore_model_gemma::{sha256, sha256_hex};

/// `(path relative to crates/claymore-cuda, SHA-256)`.
const MANIFEST: [(&str, &str); 7] = [
    (
        "kernels/claymore_math.cuh",
        "15efcd8a159db1a240355712bee4ee7ade61a1c435360dbde5af9ad40c2471f7",
    ),
    (
        "kernels/m10.cu",
        "afde273b9a3426f6ea62b2d3257d0a73db4d8ca4f5dc0e9c755726b91227b9f9",
    ),
    (
        "kernels/m8_bf16.cu",
        "2edac588d887e2f3ba091bd18aa8f02d645aa07993743ba9fd5d5babf2eff948",
    ),
    (
        "kernels/m8_f32.cu",
        "f65bd84b35ecdcdbcf2bb1c38f8e384991ba1d71e53be299d52bcbc773c19eab",
    ),
    (
        "src/kernels/m10.ptx",
        "23d308dd9368fa1b21596c246b5ea4da129fd36b197234dc5a4d93d2ab673da1",
    ),
    (
        "src/kernels/m8_bf16.ptx",
        "186ab2d533b517bd6922f026037054bb8004edd4872dd8d56541f4c2f88a7c29",
    ),
    (
        "src/kernels/m8_f32.ptx",
        "55e491b6e7217180c43deb4abcb17ae6ee946a0fe60a6e5f4940dfc8429b9e15",
    ),
];

fn cuda_crate_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../claymore-cuda")
}

#[test]
fn cuda_sources_and_ptx_match_the_committed_provenance_manifest() {
    let root = cuda_crate_root();
    let mut mismatches = Vec::new();
    for (relative, expected) in MANIFEST {
        let path = root.join(relative);
        let bytes = std::fs::read(&path)
            .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()));
        let actual = sha256_hex(&sha256(&bytes));
        if actual != expected {
            mismatches.push(format!("{relative}: expected {expected}, found {actual}"));
        }
    }
    assert!(
        mismatches.is_empty(),
        "CUDA kernel provenance broken (regenerate the PTX with nvcc 13.0 \
         -fmad=false, replay the GPU campaign, then update MANIFEST in this \
         file and section 8.2 of the parity report):\n{}",
        mismatches.join("\n")
    );
}

#[test]
fn every_versioned_ptx_and_cuda_source_is_in_the_manifest() {
    let root = cuda_crate_root();
    for (dir, extensions) in [
        ("kernels", &["cu", "cuh"][..]),
        ("src/kernels", &["ptx"][..]),
    ] {
        let mut found = Vec::new();
        for entry in std::fs::read_dir(root.join(dir)).expect("kernel directory") {
            let path = entry.expect("directory entry").path();
            let is_kernel_file = path
                .extension()
                .and_then(|extension| extension.to_str())
                .is_some_and(|extension| extensions.contains(&extension));
            if is_kernel_file {
                let name = path.file_name().unwrap().to_string_lossy().into_owned();
                found.push(format!("{dir}/{name}"));
            }
        }
        for relative in found {
            assert!(
                MANIFEST.iter().any(|(listed, _)| *listed == relative),
                "{relative} is versioned but absent from the provenance manifest"
            );
        }
    }
}
